reactiveclass Hub {
	knownrebecs {
		Client clients[5];
	}
	statevars {
		int clientCount;
	}
	msgsrv initial() {
		clientCount = 0;
	}
	msgsrv Register(Client ref) {
		if (clientCount < 5) {
			clients[clientCount] = ref;
			clientCount = clientCount + 1;
		}
	}
	msgsrv Ping() {
		sender.Pong();
	}
}

main {
	Hub hub();
	Client c1(hub): (hub);
	Client c2(hub): (hub);
	Client c3(hub): (hub);
	Client c4(hub): (hub);
	Client c5(hub): (hub);

	hub.Register(c1);
	c1.start();

	hub.Register(c2);
	c2.start();

	hub.Register(c3);
	c3.start();

	hub.Register(c4);
	c4.start();

	hub.Register(c5);
	c5.start();
}

